import{_ as p,a0 as d,w as o,s as r,I as t,x as e,a1 as a,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands","title":"LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands.md","filePath":"[post].md"}'),g={name:"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands.md"};function h(c,s,k,u,v,b){const i=d("Link");return o(),r("div",null,[s[33]||(s[33]=t("h1",{id:"lfcs-系列第十一讲-如何使用命令-vgcreate、lvcreate-和-lvextend-管理和创建-lvm",tabindex:"-1"},[e("LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM "),t("a",{class:"header-anchor",href:"#lfcs-系列第十一讲-如何使用命令-vgcreate、lvcreate-和-lvextend-管理和创建-lvm","aria-label":"Permalink to “LFCS 系列第十一讲：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和创建 LVM”"},"​")],-1)),t("p",null,[s[2]||(s[2]=e("由于 LFCS 考试中的一些改变已在 2016 年 2 月 2 日生效，我们添加了一些必要的专题到 ",-1)),a(i,{href:"https://linux.cn/article-7161-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("LFCS 系列",-1)])]),_:1}),s[3]||(s[3]=e("。我们也非常推荐备考的同学，同时阅读 ",-1)),a(i,{href:"http://www.tecmint.com/installing-network-services-and-configuring-services-at-system-boot/"},{default:n(()=>[...s[1]||(s[1]=[e("LFCE 系列",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[34]||(s[34]=l('<p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Manage-LVM-and-Create-LVM-Partition-in-Linux.png" alt=""></p><p><em>LFCS：管理 LVM 和创建 LVM 分区</em></p><p>在安装 Linux 系统的时候要做的最重要的决定之一便是给系统文件、home 目录等分配空间。在这个地方犯了错，再要扩大空间不足的分区，那样既麻烦又有风险。</p><p><strong>逻辑卷管理</strong> （<strong>LVM</strong>）相较于传统的分区管理有许多优点，已经成为大多数（如果不能说全部的话） Linux 发行版安装时的默认选择。LVM 最大的优点应该是能方便的按照你的意愿调整（减小或增大）逻辑分区的大小。</p><p>LVM 的组成结构：</p><ul><li>把一块或多块硬盘或者一个或多个分区配置成物理卷（PV）。</li><li>一个用一个或多个物理卷创建出的卷组（<strong>VG</strong>）。可以把一个卷组想象成一个单独的存储单元。</li><li>在一个卷组上可以创建多个逻辑卷。每个逻辑卷相当于一个传统意义上的分区 —— 优点是它的大小可以根据需求重新调整大小，正如之前提到的那样。</li></ul><p>本文，我们将使用三块 <strong>8 GB</strong> 的磁盘（<strong>/dev/sdb</strong>、<strong>/dev/sdc</strong> 和 <strong>/dev/sdd</strong>）分别创建三个物理卷。你既可以直接在整个设备上创建 PV，也可以先分区在创建。</p>',7)),t("p",null,[s[6]||(s[6]=e("在这里我们选择第一种方式，如果你决定使用第二种（可以参考本系列",-1)),a(i,{href:"https://linux.cn/article-7187-1.html"},{default:n(()=>[...s[5]||(s[5]=[e("第四讲：创建分区和文件系统",-1)])]),_:1}),s[7]||(s[7]=e("）确保每个分区的类型都是 ",-1)),s[8]||(s[8]=t("code",null,"8e",-1)),s[9]||(s[9]=e("。",-1))]),s[35]||(s[35]=l(`<h3 id="创建物理卷-卷组和逻辑卷" tabindex="-1">创建物理卷，卷组和逻辑卷 <a class="header-anchor" href="#创建物理卷-卷组和逻辑卷" aria-label="Permalink to “创建物理卷，卷组和逻辑卷”">​</a></h3><p>要在 <strong>/dev/sdb</strong>、<strong>/dev/sdc</strong> 和 <strong>/dev/sdd</strong>上创建物理卷，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvcreate /dev/sdb /dev/sdc /dev/sdd</span></span></code></pre></div><p>你可以列出新创建的 PV ，通过：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvs</span></span></code></pre></div><p>并得到每个 PV 的详细信息，通过：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvdisplay /dev/sdX</span></span></code></pre></div><p>（<strong>X</strong> 即 b、c 或 d）</p><p>如果没有输入 <code>/dev/sdX</code> ，那么你将得到所有 PV 的信息。</p><p>使用 /dev/sdb<code>和</code>/dev/sdc<code>创建卷组 ，命名为</code>vg00<code>(在需要时是可以通过添加其他设备来扩展空间的，我们等到说明这点的时候再用，所以暂时先保留</code>/dev/sdd\`）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgcreate vg00 /dev/sdb /dev/sdc</span></span></code></pre></div><p>就像物理卷那样，你也可以查看卷组的信息，通过：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgdisplay vg00</span></span></code></pre></div><p>由于 <code>vg00</code> 是由两个 <strong>8 GB</strong> 的磁盘组成的，所以它将会显示成一个 <strong>16 GB</strong> 的硬盘：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-LVM-Volume-Groups.png" alt=""></p><p><em>LVM 卷组列表</em></p><p>当谈到创建逻辑卷，空间的分配必须考虑到当下和以后的需求。根据每个逻辑卷的用途来命名是一个好的做法。</p><p>举个例子，让我们创建两个 LV，命名为 <code>vol_projects</code> （<strong>10 GB</strong>） 和 <code>vol_backups</code> （剩下的空间）， 在日后分别用于部署项目文件和系统备份。</p><p>参数 <code>-n</code> 用于为 LV 指定名称，而 <code>-L</code> 用于设定固定的大小，还有 <code>-l</code> （小写的 L）在 VG 的预留空间中用于指定百分比大小的空间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvcreate -n vol_projects -L 10G vg00</span></span>
<span class="line"><span># lvcreate -n vol_backups -l 100%FREE vg00</span></span></code></pre></div><p>和之前一样，你可以查看 LV 的列表和基础信息，通过：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvs</span></span></code></pre></div><p>或是查看详细信息，通过：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvdisplay</span></span></code></pre></div><p>若要查看单个 <strong>LV</strong> 的信息，使用 <strong>lvdisplay</strong> 加上 <strong>VG</strong> 和 <strong>LV</strong> 作为参数，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvdisplay vg00/vol_projects</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-Logical-Volume.png" alt=""></p><p><em>逻辑卷列表</em></p><p>如上图，我们看到 LV 已经被创建成存储设备了（参考 LV Path 那一行）。在使用每个逻辑卷之前，需要先在上面创建文件系统。</p><p>这里我们拿 ext4 来做举例，因为对于每个 LV 的大小， ext4 既可以增大又可以减小（相对的 xfs 就只允许增大）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkfs.ext4 /dev/vg00/vol_projects</span></span>
<span class="line"><span># mkfs.ext4 /dev/vg00/vol_backups</span></span></code></pre></div><p>我们将在下一节向大家说明，如何调整逻辑卷的大小并在需要的时候添加额外的外部存储空间。</p><h3 id="调整逻辑卷大小和扩充卷组" tabindex="-1">调整逻辑卷大小和扩充卷组 <a class="header-anchor" href="#调整逻辑卷大小和扩充卷组" aria-label="Permalink to “调整逻辑卷大小和扩充卷组”">​</a></h3><p>现在设想以下场景。<code>vol_backups</code> 中的空间即将用完，而 <code>vol_projects</code> 中还有富余的空间。由于 LVM 的特性，我们可以轻易的减小后者的大小（比方说 <strong>2.5 GB</strong>），并将其分配给前者，与此同时调整每个文件系统的大小。</p><p>幸运的是这很简单，只需：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvreduce -L -2.5G -r /dev/vg00/vol_projects</span></span>
<span class="line"><span># lvextend -l +100%FREE -r /dev/vg00/vol_backups</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Resize-Reduce-Logical-Volume-and-Volume-Group.png" alt=""></p><p><em>减小逻辑卷和卷组</em></p><p>在调整逻辑卷的时候，其中包含的减号 <code>(-)</code> 或加号 <code>(+)</code> 是十分重要的。否则 LV 将会被设置成指定的大小，而非调整指定大小。</p><p>有些时候，你可能会遭遇那种无法仅靠调整逻辑卷的大小就可以解决的问题，那时你就需要购置额外的存储设备了，你可能需要再加一块硬盘。这里我们将通过添加之前配置时预留的 PV （<code>/dev/sdd</code>），用以模拟这种情况。</p><p>想把 <code>/dev/sdd</code> 加到 <code>vg00</code>，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgextend vg00 /dev/sdd</span></span></code></pre></div><p>如果你在运行上条命令的前后执行 vgdisplay <code>vg00</code> ，你就会看出 VG 的大小增加了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgdisplay vg00</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-Volume-Group-Size.png" alt=""></p><p><em>查看卷组磁盘大小</em></p><p>现在，你可以使用新加的空间，按照你的需求调整现有 LV 的大小，或者创建一个新的 LV。</p><h3 id="在启动和需求时挂载逻辑卷" tabindex="-1">在启动和需求时挂载逻辑卷 <a class="header-anchor" href="#在启动和需求时挂载逻辑卷" aria-label="Permalink to “在启动和需求时挂载逻辑卷”">​</a></h3><p>当然，如果我们不打算实际的使用逻辑卷，那么创建它们就变得毫无意义了。为了更好的识别逻辑卷，我们需要找出它的 <code>UUID</code> （用于识别一个格式化存储设备的唯一且不变的属性）。</p><p>要做到这点，可使用 blkid 加每个设备的路径来实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># blkid /dev/vg00/vol_projects</span></span>
<span class="line"><span># blkid /dev/vg00/vol_backups</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Find-Logical-Volume-UUID.png" alt=""></p><p><em>寻找逻辑卷的 UUID</em></p><p>为每个 LV 创建挂载点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkdir /home/projects</span></span>
<span class="line"><span># mkdir /home/backups</span></span></code></pre></div><p>并在 <code>/etc/fstab</code> 插入相应的条目（确保使用之前获得的UUID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UUID=b85df913-580f-461c-844f-546d8cde4646 /home/projects    ext4 defaults 0 0</span></span>
<span class="line"><span>UUID=e1929239-5087-44b1-9396-53e09db6eb9e /home/backups ext4    defaults 0 0</span></span></code></pre></div><p>保存并挂载 LV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -a</span></span>
<span class="line"><span># mount | grep home</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Mount-Logical-Volumes-on-Linux-1.png" alt=""></p><p><em>挂载逻辑卷</em></p>`,61)),t("p",null,[s[11]||(s[11]=e("在涉及到 LV 的实际使用时，你还需要按照曾在本系列",-1)),a(i,{href:"https://linux.cn/article-7418-1.html"},{default:n(()=>[...s[10]||(s[10]=[e("第八讲：管理用户和用户组",-1)])]),_:1}),s[12]||(s[12]=e("中讲解的那样，为其设置合适的 ",-1)),s[13]||(s[13]=t("code",null,"ugo+rwx",-1)),s[14]||(s[14]=e("。",-1))]),s[36]||(s[36]=t("h3",{id:"总结",tabindex:"-1"},[e("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t("p",null,[s[17]||(s[17]=e("本文介绍了 ",-1)),a(i,{href:"https://linux.cn/article-3965-1.html"},{default:n(()=>[...s[15]||(s[15]=[e("逻辑卷管理",-1)])]),_:1}),s[18]||(s[18]=e("，一个用于管理可扩展存储设备的多功能工具。与 RAID（曾在本系列讲解过的 ",-1)),a(i,{href:"https://linux.cn/article-7229-1.html"},{default:n(()=>[...s[16]||(s[16]=[e("第六讲：组装分区为RAID设备——创建和管理系统备份",-1)])]),_:1}),s[19]||(s[19]=e("）结合使用，你将同时体验到（LVM 带来的）可扩展性和（RAID 提供的）冗余。",-1))]),s[37]||(s[37]=t("p",null,[e("在这类的部署中，你通常会在 "),t("code",null,"RAID"),e(" 上发现 "),t("code",null,"LVM"),e("，这就是说，要先配置好 RAID 然后它在上面配置 LVM。")],-1)),s[38]||(s[38]=t("p",null,"如果你对本问有任何的疑问和建议，可以直接在下方的评论区告诉我们。",-1)),s[39]||(s[39]=t("hr",null,null,-1)),t("p",null,[s[21]||(s[21]=e("via: ",-1)),a(i,{href:"http://www.tecmint.com/manage-and-create-lvm-parition-using-vgcreate-lvcreate-and-lvextend/"},{default:n(()=>[...s[20]||(s[20]=[e("http://www.tecmint.com/manage-and-create-lvm-parition-using-vgcreate-lvcreate-and-lvextend/",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=e("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...s[22]||(s[22]=[e("Gabriel Cánepa",-1)])]),_:1}),s[26]||(s[26]=e(" 译者：",-1)),a(i,{href:"https://github.com/martin2011qi"},{default:n(()=>[...s[23]||(s[23]=[e("martin2011qi",-1)])]),_:1}),s[27]||(s[27]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[28]||(s[28]=[e("LCTT",-1)])]),_:1}),s[31]||(s[31]=e(" 原创翻译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[29]||(s[29]=[e("Linux中国",-1)])]),_:1}),s[32]||(s[32]=e(" 荣誉推出",-1))])])}const C=p(g,[["render",h]]);export{L as __pageData,C as default};
